from bs4 import BeautifulSoup
import requests

def parse_html_for_links(url):
    response = requests.get(url)
    soup = BeautifulSoup(response.text, 'html.parser')

    links = []
    for link in soup.find_all('a', href=True):
        href = link['href']
        if href.startswith('http'):
            links.append(href)

    return links

def filter_unique_links(links):
    unique_links = []
    for link in links:
        if link not in unique_links:
            unique_links.append(link)
    return unique_links

def main():
    url = 'https://example.com'
    all_links = parse_html_for_links(url)
    unique_links = filter_unique_links(all_links)

    print("Unique links found:")
    for link in unique_links:
        print(link)

if __name__ == '__main__':
    main()

import logging
from logging import Formatter, Handler

class CustomFormatter(Formatter):
    def __init__(self, fmt=None, datefmt=None):
        super().__init__(fmt=fmt, datefmt=datefmt)

    def format(self, record):
        if record.levelno == logging.ERROR:
            return f"Error: {record.getMessage()}"
        elif record.levelno == logging.WARNING:
            return f"Warning: {record.getMessage()}"
        else:
            return super().format(record)

class CustomHandler(Handler):
    def emit(self, record):
        log_entry = self.format(record)
        print(log_entry)

def setup_logger():
    logger = logging.getLogger('custom_logger')
    logger.setLevel(logging.DEBUG)

    formatter = CustomFormatter(fmt='%(asctime)s - %(levelname)s - %(message)s', datefmt='%Y-%m-%d %H:%M:%S')
    handler = CustomHandler()
    handler.setFormatter(formatter)

    logger.addHandler(handler)
    return logger

if __name__ == "__main__":
    logger = setup_logger()
    logger.debug("This is a debug message")
    logger.info("This is an info message")
    logger.warning("This is a warning message")
    logger.error("This is an error message")

