class StockPriceObserver:
    def __init__(self):
        self.prices = {}

    def update_price(self, symbol, price):
        self.prices[symbol] = price
        print(f"Updated price for {symbol}: {price}")

class StockPriceSubject:
    def __init__(self):
        self.observers = []

    def add_observer(self, observer):
        self.observers.append(observer)

    def remove_observer(self, observer):
        self.observers.remove(observer)

    def notify_observers(self, symbol, price):
        for observer in self.observers:
            observer.update_price(symbol, price)

def main():
    subject = StockPriceSubject()
    observer = StockPriceObserver()
    subject.add_observer(observer)

    while True:
        symbol = input("Enter stock symbol (or 'quit' to exit): ")
        if symbol.lower() == 'quit':
            break
        price = float(input("Enter stock price: "))
        subject.notify_observers(symbol, price)

if __name__ == "__main__":
    main()

import logging

class CustomFormatter(logging.Formatter):
    def __init__(self, fmt=None, datefmt=None):
        super().__init__(fmt, datefmt)

    def format(self, record):
        log_message = super().format(record)
        return f"[{recordasctime}] {log_message}"

class CustomHandler(logging.Handler):
    def emit(self, record):
        log_entry = self.format(record)
        print(log_entry)

def setup_logger():
    logger = logging.getLogger("custom_logger")
    logger.setLevel(logging.INFO)

    formatter = CustomFormatter(fmt="%(asctime)s - %(levelname)s - %(message)s", datefmt="%Y-%m-%d %H:%M:%S")
    handler = CustomHandler()
    handler.setFormatter(formatter)

    logger.addHandler(handler)
    return logger

logger = setup_logger()

