def apply_threshold(image_data, threshold_value):
    return np.where(image_data > threshold_value, 1, 0)

def resize_image(image_array, factor):
    height, width = image_array.shape[:2]
    new_height = int(height * factor)
    new_width = int(width * factor)
    return cv2.resize(image_array, (new_width, new_height))

def crop_image(image_array, start_row, end_row, start_col, end_col):
    return image_array[start_row:end_row, start_col:end_col]

