async def get_ec2_spend_last_day(params: EC2Params) -> Dict[str, Any]:
    print(f"get_ec2_spend_last_day, params={params}")
    # Initialize the Cost Explorer client
    ce_client = get_aws_service_boto3_client("ce", params.aws_account_id, params.region)


    # Calculate the time period - last day
    end_date = datetime.now().strftime('%Y-%m-%d')
    start_date = (datetime.now() - timedelta(days=1)).strftime('%Y-%m-%d')

    try:
        # Make the API call using get_cost_and_usage (standard API)
        response = ce_client.get_cost_and_usage(
            TimePeriod={
                'Start': start_date,
                'End': end_date
            },
            Granularity='DAILY',
            Filter={
                'Dimensions': {
                    'Key': 'SERVICE',
                    'Values': [
                        'Amazon Elastic Compute Cloud - Compute'
                    ]
                }
            },
            Metrics=[
                'UnblendedCost',
                'UsageQuantity'
            ],
            GroupBy=[
                {
                    'Type': 'DIMENSION',
                    'Key': 'INSTANCE_TYPE'
                }
            ]
        )

        # Process and print the results
        print(f"EC2 Spend from {start_date} to {end_date}:")
        print("-" * 50)

        total_cost = 0.0

        if 'ResultsByTime' in response and response['ResultsByTime']:
            time_period_data = response['ResultsByTime'][0]

            if 'Groups' in time_period_data:
                for group in time_period_data['Groups']:
                    instance_type = group['Keys'][0]
                    cost = float(group['Metrics']['UnblendedCost']['Amount'])
                    currency = group['Metrics']['UnblendedCost']['Unit']
                    usage = float(group['Metrics']['UsageQuantity']['Amount'])

                    print(f"Instance Type: {instance_type}")
                    print(f"Cost: {cost:.4f} {currency}")
                    print(f"Usage: {usage:.2f}")
                    print("-" * 30)

                    total_cost += cost

            # If no instance-level breakdown, show total
            if not time_period_data.get('Groups'):
                if 'Total' in time_period_data:
                    total = time_period_data['Total']
                    cost = float(total['UnblendedCost']['Amount'])
                    currency = total['UnblendedCost']['Unit']
                    print(f"Total EC2 Cost: {cost:.4f} {currency}")
                else:
                    print("No EC2 costs found for this period")
            else:
                print(f"Total EC2 Cost: {total_cost:.4f} {currency if 'currency' in locals() else 'USD'}")

            # Check if results are estimated
            if 'Estimated' in time_period_data:
                print(f"Note: These results are {'estimated' if time_period_data['Estimated'] else 'final'}")

        return response

    except Exception as e:
        print(f"Error retrieving EC2 cost data: {str(e)}")
        return None

def consult_codex_batch(
    queries: List[Dict[str, Union[str, int]]],
    directory: str,
    format: str = "json"
) -> str:
    # Check if codex CLI is available
    if not _get_codex_command():
        return json.dumps({
            "status": "error",
            "error": "Codex CLI not found. Install from OpenAI"
        }, indent=2)

    # Validate directory
    if not os.path.isdir(directory):
        return json.dumps({
            "status": "error",
            "error": f"Directory does not exist: {directory}"
        }, indent=2)

    # Validate queries
    if not queries or not isinstance(queries, list):
        return json.dumps({
            "status": "error",
            "error": "Queries must be a non-empty list"
        }, indent=2)

    # Force JSON format for batch processing
    format = "json"
    results = []

    for i, query_item in enumerate(queries):
        if not isinstance(query_item, dict) or 'query' not in query_item:
            results.append({
                "status": "error",
                "error": f"Query {i+1}: Must be a dictionary with 'query' key",
                "index": i
            })
            continue

        query = str(query_item.get('query', ''))
        query_timeout = query_item.get('timeout', _get_timeout())
        if isinstance(query_timeout, str):
            try:
                query_timeout = int(query_timeout)
            except ValueError:
                query_timeout = _get_timeout()

        # Process individual query
        processed_query = _format_prompt_for_json(query)
        cmd = ["codex", "exec"]
        if _should_skip_git_check():
            cmd.append("--skip-git-repo-check")

        start_time = time.time()
        try:
            result = _run_codex_command(cmd, directory, query_timeout, processed_query)
            execution_time = time.time() - start_time

            if result.returncode == 0:
                cleaned_output = _clean_codex_output(result.stdout)
                raw_response = cleaned_output if cleaned_output else "No output from Codex CLI"

                # Try to extract JSON from response
                extracted_json = _extract_json_from_response(raw_response)

                results.append({
                    "status": "success",
                    "index": i,
                    "query": query[:100] + "..." if len(query) > 100 else query,  # Truncate long queries
                    "response": extracted_json if extracted_json else raw_response,
                    "metadata": {
                        "execution_time": execution_time,
                        "timeout": query_timeout
                    }
                })
            else:
                results.append({
                    "status": "error",
                    "index": i,
                    "query": query[:100] + "..." if len(query) > 100 else query,
                    "error": f"Codex CLI Error: {result.stderr.strip()}",
                    "metadata": {
                        "execution_time": execution_time,
                        "timeout": query_timeout
                    }
                })

        except subprocess.TimeoutExpired:
            results.append({
                "status": "error",
                "index": i,
                "query": query[:100] + "..." if len(query) > 100 else query,
                "error": f"Query timed out after {query_timeout} seconds",
                "metadata": {
                    "timeout": query_timeout
                }
            })
        except Exception as e:
            results.append({
                "status": "error",
                "index": i,
                "query": query[:100] + "..." if len(query) > 100 else query,
                "error": f"Error executing query: {str(e)}",
                "metadata": {}
            })

    # Return consolidated results
    return json.dumps({
        "status": "completed",
        "total_queries": len(queries),
        "successful": len([r for r in results if r["status"] == "success"]),
        "failed": len([r for r in results if r["status"] == "error"]),
        "results": results,
        "metadata": {
            "directory": directory,
            "format": format
        }
    }, indent=2)

