import argparse

def parse_arguments():
    parser = argparse.ArgumentParser(description="CLI tool for managing file operations")
    parser.add_argument('--file_path', type=str, required=True, help='Path to the input file')
    parser.add_argument('--mode', type=str, choices=['read', 'write'], default='read', help='Operation mode: read or write')
    parser.add_argument('--append_text', type=str, default='', help='Text to append if mode is write')
    return parser.parse_args()

def main():
    args = parse_arguments()

    if args.mode == 'read':
        with open(args.file_path, 'r') as file:
            content = file.read()
            print("File content:", content)
    elif args.mode == 'write':
        with open(args.file_path, 'a') as file:
            file.write(args.append_text)
        print(f"Appended '{args.append_text}' to {args.file_path}")

if __name__ == "__main__":
    main()

