from bs4 import BeautifulSoup
import requests

def parse_html_for_links(url):
    response = requests.get(url)
    soup = BeautifulSoup(response.content, 'html.parser')

    links = []
    for anchor in soup.find_all('a', href=True):
        link = anchor['href']
        if link.startswith('http'):
            links.append(link)

    return links

def filter_unique_links(links):
    unique_links = []
    seen = set()
    for link in links:
        if link not in seen:
            unique_links.append(link)
            seen.add(link)
    return unique_links

def main():
    url = "https://example.com"
    all_links = parse_html_for_links(url)
    unique_links = filter_unique_links(all_links)
    print(unique_links)

if __name__ == "__main__":
    main()

