class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, item_name, quantity):
        self.items.append({"item_name": item_name, "quantity": quantity})
        print(f"Added {quantity}x {item_name} to cart.")

    def remove_item(self, item_name, quantity):
        for item in self.items:
            if item["item_name"] == item_name:
                if item["quantity"] >= quantity:
                    item["quantity"] -= quantity
                    print(f"Removed {quantity}x {item_name} from cart.")
                    return
                else:
                    print(f"Not enough {item_name} in cart to remove.")
                    return
        print(f"{item_name} not found in cart.")

    def display_cart(self):
        if not self.items:
            print("Cart is empty.")
            return
        for item in self.items:
            print(f"{item['quantity']}x {item['item_name']}")

