def consult_codex(
    query: str,
    directory: str,
    format: str = "json",
    timeout: Optional[int] = None
) -> str:
    # Check if codex CLI is available
    if not _get_codex_command():
        error_response = "Error: Codex CLI not found. Install from OpenAI"
        if format == "json":
            return json.dumps({"status": "error", "error": error_response}, indent=2)
        return error_response

    # Validate directory
    if not os.path.isdir(directory):
        error_response = f"Error: Directory does not exist: {directory}"
        if format == "json":
            return json.dumps({"status": "error", "error": error_response}, indent=2)
        return error_response

    # Validate format
    if format not in ["text", "json", "code"]:
        error_response = f"Error: Invalid format '{format}'. Must be 'text', 'json', or 'code'"
        # Always return JSON for invalid format errors for consistency
        return json.dumps({"status": "error", "error": error_response}, indent=2)

    # Prepare query based on format
    if format == "json":
        processed_query = _format_prompt_for_json(query)
    else:
        processed_query = query

    # Setup command and timeout
    cmd = ["codex", "exec"]
    if _should_skip_git_check():
        cmd.append("--skip-git-repo-check")
    timeout_value = timeout or _get_timeout()

    # Execute with timing
    start_time = time.time()
    try:
        result = _run_codex_command(cmd, directory, timeout_value, processed_query)
        execution_time = time.time() - start_time

        if result.returncode == 0:
            cleaned_output = _clean_codex_output(result.stdout)
            raw_response = cleaned_output if cleaned_output else "No output from Codex CLI"
            return _format_response(raw_response, format, execution_time, directory)
        else:
            error_response = f"Codex CLI Error: {result.stderr.strip()}"
            if format == "json":
                return json.dumps({
                    "status": "error",
                    "error": error_response,
                    "metadata": {
                        "execution_time": execution_time,
                        "directory": directory,
                        "format": format
                    }
                }, indent=2)
            return error_response

    except subprocess.TimeoutExpired:
        error_response = f"Error: Codex CLI command timed out after {timeout_value} seconds"
        if format == "json":
            return json.dumps({
                "status": "error",
                "error": error_response,
                "metadata": {
                    "timeout": timeout_value,
                    "directory": directory,
                    "format": format
                }
            }, indent=2)
        return error_response
    except Exception as e:
        error_response = f"Error executing Codex CLI: {str(e)}"
        if format == "json":
            return json.dumps({
                "status": "error", 
                "error": error_response,
                "metadata": {
                    "directory": directory,
                    "format": format
                }
            }, indent=2)
        return error_response

def subscribe_to_ticker_stream(symbol: str) -> dict:
        symbol = symbol.lower()
        stream_name = f"{symbol}@ticker"

        # Check if already subscribed
        if stream_name in active_subscriptions:
            return {
                "status": "already_subscribed",
                "stream": stream_name,
                "message": f"Already subscribed to ticker stream for {symbol}"
            }

        # Create a queue for this stream's data
        data_queues[stream_name] = Queue(maxsize=100)

        # Set up callback function
        async def callback(data):
            await handle_stream_message(stream_name, data)

        # Run the subscription in a background task
        async def subscribe_task():
            success = await binance_ws_api.subscribe_to_ticker_stream(symbol, callback)
            if success:
                active_subscriptions[stream_name] = {
                    "type": "ticker",
                    "symbol": symbol
                }

        # Use create_task for async operations
        asyncio.create_task(subscribe_task())

        return {
            "status": "subscribing",
            "stream": stream_name,
            "message": f"Subscribing to ticker stream for {symbol}"
        }

def binary_search(arr, target):
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

def merge_sort(arr):
    if len(arr) > 1:
        mid = len(arr) // 2
        left_half = arr[:mid]
        right_half = arr[mid:]

        merge_sort(left_half)
        merge_sort(right_half)

        i = j = k = 0

        while i < len(left_half) and j < len(right_half):
            if left_half[i] < right_half[j]:
                arr[k] = left_half[i]
                i += 1
            else:
                arr[k] = right_half[j]
                j += 1
            k += 1

        while i < len(left_half):
            arr[k] = left_half[i]
            i += 1
            k += 1

        while j < len(right_half):
            arr[k] = right_half[j]
            j += 1
            k += 1

    return arr

if __name__ == "__main__":
    nums = [38, 27, 43, 3, 9, 82, 10]
    sorted_nums = merge_sort(nums.copy())
    print("Sorted array:", sorted_nums)

    target = 3
    index = binary_search(sorted_nums, target)
    print(f"Index of {target} in sorted array:", index)

