from abc import ABC, abstractmethod

class Observable(ABC):
    def __init__(self):
        self._observers = []

    def add_observer(self, observer):
        self._observers.append(observer)

    def remove_observer(self, observer):
        self._observers.remove(observer)

    def notify_observers(self, event):
        for observer in self._observers:
            observer.update(event)


class WeatherStation(Observable):
    def __init__(self):
        super().__init__()
        self._temperature = 0
        self._humidity = 0

    @property
    def temperature(self):
        return self._temperature

    @temperature.setter
    def temperature(self, value):
        if value != self._temperature:
            self._temperature = value
            self.notify_observers(f"Temperature changed to {value}°C")

    @property
    def humidity(self):
        return self._humidity

    @humidity.setter
    def humidity(self, value):
        if value != self._humidity:
            self._humidity = value
            self.notify_observers(f"Humidity changed to {value}%")


class ConsoleObserver:
    def update(self, event):
        print(f"Console received: {event}")


class EmailObserver:
    def update(self, event):
        print(f"Email sent: {event}")


if __name__ == "__main__":
    weather_station = WeatherStation()
    console_observer = ConsoleObserver()
    email_observer = EmailObserver()

    weather_station.add_observer(console_observer)
    weather_station.add_observer(email_observer)

