class TreeNode:
    def __init__(self, value):
        self.value = value
        self.children = []

def build_tree(root_value, values):
    root = TreeNode(root_value)
    queue = [root]

    for value in values:
        current = queue.pop(0)
        if len(current.children) < 2:
            child = TreeNode(value)
            current.children.append(child)
            queue.append(child)

    return root

def traverse_tree(node, result):
    if not node:
        return

    result.append(node.value)
    for child in node.children:
        traverse_tree(child, result)

def main():
    root_value = "A"
    values = ["B", "C", "D", "E", "F", "G"]
    root = build_tree(root_value, values)

    result = []
    traverse_tree(root, result)

    print("Tree traversal:", result)

if __name__ == "__main__":
    main()

