import os

def load_image_files(image_dir):
    image_files = []
    supported_extensions = ['.jpg', '.jpeg', '.png', '.bmp']
    for root, dirs, files in os.walk(image_dir):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in supported_extensions:
                image_files.append(os.path.join(root, file))
    return image_files

def resize_image(image_path, width, height):
    from PIL import Image
    img = Image.open(image_path)
    resized_img = img.resize((width, height), Image.ANTIALIAS)
    resized_img.save(image_path)

def process_images(image_dir, output_dir, width, height):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    images = load_image_files(image_dir)
    for image_path in images:
        base_name = os.path.basename(image_path)
        output_path = os.path.join(output_dir, base_name)
        resize_image(image_path, width, height)
        print(f"Resized {image_path} to {output_path}")

if __name__ == "__main__":
    input_dir = "input_images"
    output_dir = "resized_images"
    new_width = 800
    new_height = 600
    process_images(input_dir, output_dir, new_width, new_height)

def binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def merge_sort(arr):
    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left_half = merge_sort(arr[:mid])
    right_half = merge_sort(arr[mid:])

    return merge(left_half, right_half)

def merge(left, right):
    merged = []
    left_index, right_index = 0, 0

    while left_index < len(left) and right_index < len(right):
        if left[left_index] < right[right_index]:
            merged.append(left[left_index])
            left_index += 1
        else:
            merged.append(right[right_index])
            right_index += 1

    merged.extend(left[left_index:])
    merged.extend(right[right_index:])

    return merged

if __name__ == "__main__":
    data = [34, 7, 23, 32, 5, 62]
    sorted_data = merge_sort(data)
    print("Sorted Data:", sorted_data)

    target = 23
    result = binary_search(sorted_data, target)
    print(f"Target {target} found at index: {result}")

