from pydantic import BaseModel, validator

class UserInput(BaseModel):
    name: str
    email: str
    age: int
    preferences: list[str]

    @validator('name')
    def validate_name(cls, v):
        if not v.isalpha():
            raise ValueError("Name should only contain alphabetic characters")
        return v.title()

    @validator('email')
    def validate_email(cls, v):
        parts = v.split('@')
        if len(parts) != 2 or not parts[1]:
            raise ValueError("Invalid email format")
        return v.lower()

    @validator('age')
    def validate_age(cls, v):
        if v < 18 or v > 100:
            raise ValueError("Age must be between 18 and 100")
        return v

    @validator('preferences')
    def validate_preferences(cls, v):
        if not all(isinstance(x, str) for x in v):
            raise ValueError("All preferences must be strings")
        return v

def check_user_input(data: dict):
    try:
        validated_data = UserInput(**data)
        print("Input is valid:", validated_data.dict())
    except ValueError as e:
        print("Validation error:", e)

