    users = [
        {"name": "Alice", "email": "alice@example.com", "age": 28, "bio": "Software developer"},
        {"name": "Bob", "email": "bob@sample.net", "age": 34, "bio": "System administrator"},
        {"name": "Charlie", "email": "charlie@test.org", "age": 42, "bio": "Data scientist"}
    ]

